def normalize_visible(text: str, *, markdown: bool) -> str:
    """Remove presentation syntax and whitespace only; keep every visible symbol."""
    if markdown:
        text = re.sub(r"<div\b[^>]*>\s*</div>", "", text)
        text = re.sub(r"(?m)^#{1,6}\s+", "", text)
        text = re.sub(r"!?\[([^\]]*)\]\([^)]*\)", r"\1", text)
        text = text.replace("**", "")
        text = re.sub(r"`([^`]*)`", r"\1", text)
    return "".join(unicodedata.normalize("NFC", text).split())
